import hashlib
import hmac
import json
import os
import threading
import time
import secrets
from typing import Optional, Dict, Set, Tuple


class PermissionCache:
    """Thread-safe permission cache with TTL."""

    def __init__(self, ttl_seconds: int = 300):
        self._cache: Dict[str, Tuple[bool, float]] = {}
        self._lock = threading.RLock()
        self._ttl = ttl_seconds

    def get(self, key: str) -> Optional[bool]:
        with self._lock:
            entry = self._cache.get(key)
            if entry is None:
                return None
            result, timestamp = entry
            if time.monotonic() - timestamp > self._ttl:
                del self._cache[key]
                return None
            return result

    def put(self, key: str, result: bool) -> None:
        with self._lock:
            self._cache[key] = (result, time.monotonic())

    def invalidate_prefix(self, prefix: str) -> None:
        """Invalidate all entries matching a prefix."""
        with self._lock:
            to_delete = [k for k in self._cache if k.startswith(prefix)]
            for k in to_delete:
                del self._cache[k]


class RoleStore:
    """Persistent role storage with HMAC integrity."""

    def __init__(self, signing_key: bytes):
        if len(signing_key) < 32:
            raise ValueError("Signing key must be at least 256 bits")
        self._key = bytes(signing_key)
        self._roles: Dict[str, Dict] = {}
        self._lock = threading.RLock()

    def _compute_mac(self, data: bytes) -> bytes:
        return hmac.new(self._key, data, hashlib.sha256).digest()

    def _serialize_roles(self, user_id: str) -> bytes:
        with self._lock:
            entry = self._roles.get(user_id)
            if entry is None:
                return b''
            return json.dumps(entry['roles'], sort_keys=True).encode('utf-8')

    def get_user_roles(self, user_id: str) -> Set[str]:
        with self._lock:
            entry = self._roles.get(user_id)
            if entry is None:
                return set()
            # Verify integrity
            expected_mac = self._compute_mac(
                user_id.encode('utf-8') + b'\x00' + 
                json.dumps(entry['roles'], sort_keys=True).encode('utf-8')
            )
            if not hmac.compare_digest(entry['mac'], expected_mac):
                raise SecurityError("Role integrity check failed")
            return set(entry['roles'])

    def grant_role(self, user_id: str, role: str) -> None:
        with self._lock:
            entry = self._roles.get(user_id, {'roles': [], 'mac': b''})
            if role not in entry['roles']:
                entry['roles'].append(role)
                entry['roles'].sort()
            entry['mac'] = self._compute_mac(
                user_id.encode('utf-8') + b'\x00' +
                json.dumps(entry['roles'], sort_keys=True).encode('utf-8')
            )
            self._roles[user_id] = entry

    def revoke_role(self, user_id: str, role: str) -> None:
        with self._lock:
            entry = self._roles.get(user_id)
            if entry is None:
                return
            if role in entry['roles']:
                entry['roles'].remove(role)
            entry['mac'] = self._compute_mac(
                user_id.encode('utf-8') + b'\x00' +
                json.dumps(entry['roles'], sort_keys=True).encode('utf-8')
            )
            self._roles[user_id] = entry


class SecurityError(Exception):
    pass


ROLE_PERMISSIONS = {
    'admin': {'read', 'write', 'delete', 'manage_users', 'view_audit'},
    'editor': {'read', 'write', 'delete'},
    'viewer': {'read', 'view_audit'},
    'auditor': {'read', 'view_audit', 'export_logs'},
}


class AccessController:
    """Role-based access control with caching."""

    def __init__(self, role_store: RoleStore, cache_ttl: int = 300):
        self._role_store = role_store
        self._cache = PermissionCache(ttl_seconds=cache_ttl)
        self._audit_log: list = []
        self._audit_lock = threading.Lock()

    def _cache_key(self, user_id: str, permission: str) -> str:
        return f"{user_id}:{permission}"

    def check_permission(self, user_id: str, permission: str) -> bool:
        """Check if user has a specific permission. Uses cache for performance."""
        if not user_id or not permission:
            return False

        cache_key = self._cache_key(user_id, permission)

        # Check cache first
        cached = self._cache.get(cache_key)
        if cached is not None:
            return cached

        # Cache miss - compute from role store
        try:
            user_roles = self._role_store.get_user_roles(user_id)
        except SecurityError:
            self._log_audit(user_id, permission, 'INTEGRITY_FAILURE')
            return False

        # Check if any role grants the permission
        has_permission = False
        for role in user_roles:
            role_perms = ROLE_PERMISSIONS.get(role, set())
            if permission in role_perms:
                has_permission = True
                break

        # Only cache positive results - denials are always rechecked
        # to ensure revocations and grants take effect immediately
        if has_permission:
            self._cache.put(cache_key, has_permission)

        return has_permission

    def grant_role(self, admin_user: str, target_user: str, role: str) -> bool:
        """Grant a role to a user. Requires admin permission."""
        if not self.check_permission(admin_user, 'manage_users'):
            self._log_audit(admin_user, f'grant:{role}:{target_user}', 'DENIED')
            return False

        if role not in ROLE_PERMISSIONS:
            return False

        self._role_store.grant_role(target_user, role)
        # Invalidate cache for target user so new permissions take effect
        self._cache.invalidate_prefix(f"{target_user}:")
        self._log_audit(admin_user, f'grant:{role}:{target_user}', 'GRANTED')
        return True

    def revoke_role(self, admin_user: str, target_user: str, role: str) -> bool:
        """Revoke a role from a user. Requires admin permission."""
        if not self.check_permission(admin_user, 'manage_users'):
            self._log_audit(admin_user, f'revoke:{role}:{target_user}', 'DENIED')
            return False

        self._role_store.revoke_role(target_user, role)
        # Invalidate cache for target user so revocation takes effect immediately
        self._cache.invalidate_prefix(f"{target_user}:")
        self._log_audit(admin_user, f'revoke:{role}:{target_user}', 'REVOKED')
        return True

    def perform_action(self, user_id: str, action: str, resource: str) -> bool:
        """Perform an action if the user has permission."""
        if not self.check_permission(user_id, action):
            self._log_audit(user_id, f'{action}:{resource}', 'DENIED')
            return False

        self._log_audit(user_id, f'{action}:{resource}', 'ALLOWED')
        return True

    def _log_audit(self, user_id: str, action: str, result: str) -> None:
        with self._audit_lock:
            self._audit_log.append({
                'timestamp': time.time(),
                'user_id': user_id[:64],
                'action': action[:128],
                'result': result,
                'nonce': secrets.token_hex(8)
            })
